from dataclasses import dataclass

@dataclass(frozen=True)
class TemplateSpec:
    id: str
    block: str
    city_scope: str
    region_levels: tuple[str, ...]
    target_type: str
    reasoning: str
WCLF = ('whole', 'coarse', 'local', 'finegrain')
CLF = ('coarse', 'local', 'finegrain')
F = ('finegrain',)
TEMPLATES = {'U1': TemplateSpec('U1', 'Understanding', 'single_city', WCLF, 'vector', 'Temporal Read'), 'U2': TemplateSpec('U2', 'Understanding', 'single_city', WCLF, 'scalar', 'Temporal Compute'), 'U3': TemplateSpec('U3', 'Understanding', 'single_city', WCLF, 'category', 'Temporal Pattern'), 'U4': TemplateSpec('U4', 'Understanding', 'multi_city', WCLF, 'city_vectors', 'Temporal Read'), 'U5': TemplateSpec('U5', 'Understanding', 'multi_city', WCLF, 'city_values', 'Temporal Compute'), 'U6': TemplateSpec('U6', 'Understanding', 'multi_city', WCLF, 'city_id', 'Temporal Compare'), 'U7': TemplateSpec('U7', 'Understanding', 'single_city', CLF, 'scalar', 'Spatial Read'), 'U8': TemplateSpec('U8', 'Understanding', 'single_city', CLF, 'scalar', 'Spatial Compute'), 'U9': TemplateSpec('U9', 'Understanding', 'single_city', CLF, 'region_id', 'Spatial Pattern'), 'U10': TemplateSpec('U10', 'Understanding', 'multi_city', CLF, 'city_values', 'Spatial Read'), 'U11': TemplateSpec('U11', 'Understanding', 'multi_city', CLF, 'city_values', 'Spatial Compute'), 'U12': TemplateSpec('U12', 'Understanding', 'multi_city', CLF, 'city_id', 'Spatial Compare'), 'U13': TemplateSpec('U13', 'Understanding', 'single_city', CLF, 'vector', 'Spatial Temporal Read'), 'U14': TemplateSpec('U14', 'Understanding', 'single_city', CLF, 'scalar', 'Spatial Temporal Compute'), 'U15': TemplateSpec('U15', 'Understanding', 'single_city', CLF, 'category', 'Spatial Temporal Pattern'), 'U16': TemplateSpec('U16', 'Understanding', 'multi_city', CLF, 'city_vectors', 'Spatial Temporal Read'), 'U17': TemplateSpec('U17', 'Understanding', 'multi_city', CLF, 'city_values', 'Spatial Temporal Compute'), 'U18': TemplateSpec('U18', 'Understanding', 'multi_city', CLF, 'city_id', 'Spatial Temporal Compare'), 'P1': TemplateSpec('P1', 'Prediction', 'single_city', WCLF, 'category_pair', 'Trend Prediction'), 'P2': TemplateSpec('P2', 'Prediction', 'single_city', CLF, 'region_id_pair', 'Dominant Region Prediction'), 'P3': TemplateSpec('P3', 'Prediction', 'single_city', WCLF, 'vector_pair', 'Numerical Prediction'), 'P4': TemplateSpec('P4', 'Prediction', 'single_city', F, 'tensor_sequence_2ch', 'Finegrain Prediction'), 'P5': TemplateSpec('P5', 'Prediction', 'multi_city', WCLF, 'city_category_pair', 'Trend Prediction'), 'P6': TemplateSpec('P6', 'Prediction', 'multi_city', CLF, 'city_region_id_pair', 'Dominant Region Prediction'), 'P7': TemplateSpec('P7', 'Prediction', 'multi_city', WCLF, 'city_vector_pair', 'Numerical Prediction'), 'P8': TemplateSpec('P8', 'Prediction', 'multi_city', F, 'city_tensor_sequence_2ch', 'Finegrain Prediction')}
UNDERSTANDING_IDS = [f'U{i}' for i in range(1, 19)]
PREDICTION_IDS = [f'P{i}' for i in range(1, 9)]
ALL_TEMPLATE_IDS = UNDERSTANDING_IDS + PREDICTION_IDS
SINGLE_CITY_TEMPLATE_IDS = [tid for tid in ALL_TEMPLATE_IDS if TEMPLATES[tid].city_scope == 'single_city']
MULTI_CITY_TEMPLATE_IDS = [tid for tid in ALL_TEMPLATE_IDS if TEMPLATES[tid].city_scope == 'multi_city']
QUESTION_VARIANTS: dict[str, tuple[str, str, str]] = {'U1': ('For {city}, report the t=1..8 historical {modality} sequence of {unit_phrase}.', 'In {city}, read {modality} for {unit_phrase} at every historical step t=1 through t=8.', 'Using the displayed history for {city}, list the eight {modality} values of {unit_phrase} in time order.'), 'U2': ('For {city}, how much does {modality} of {unit_phrase} change from t={t1} to t={t2}?', 'In {city}, compute {modality}({unit_phrase}, t={t2}) minus {modality}({unit_phrase}, t={t1}).', 'What is the t={t1} to t={t2} {modality} change for {unit_phrase} in {city}?'), 'U3': ('For {city}, classify the t=1..8 {modality} pattern of {unit_phrase} as increasing, decreasing, stable, or fluctuating.', 'Does the historical {modality} sequence of {unit_phrase} in {city} increase, decrease, stay stable, or fluctuate?', 'Using t=1..8 in {city}, identify the temporal pattern of {modality} at {unit_phrase}: increasing, decreasing, stable, or fluctuating.'), 'U4': ('For each city, report the t=1..8 historical {modality} sequence at {unit_phrase}.', 'Read the eight historical {modality} values for {unit_phrase} in every city.', 'Using each displayed 8-hour history, list the {modality} sequence for {unit_phrase} in each city.'), 'U5': ('For each city, compute the {modality} change at {unit_phrase} from t={t1} to t={t2}.', 'In every city, subtract the t={t1} {modality} value of {unit_phrase} from its t={t2} value.', 'Report the t={t1} to t={t2} {modality} change for {unit_phrase} in each city.'), 'U6': ('For each city, compute the normalized {modality} change of {unit_phrase} from t={t1} to t={t2} as 2|v2-v1|/(|v1|+|v2|+epsilon). Which city is largest?', 'Which city has the greatest symmetric normalized {modality} change for {unit_phrase} between t={t1} and t={t2}, using 2|v2-v1|/(|v1|+|v2|+epsilon)?', 'Compare cities by 2|v(t={t2})-v(t={t1})|/(|v(t={t1})|+|v(t={t2})|+epsilon) for {modality} at {unit_phrase}. Which city is highest?'), 'U7': ('For {city} at t={time_step}, what is the {modality} value of {unit_phrase}?', 'At t={time_step} in {city}, read the {modality} at {unit_phrase}.', 'Using the {city} map at t={time_step}, report {modality} for {unit_phrase}.'), 'U8': ('For {city} at t={time_step}, compute {modality}({rid_a}) minus {modality}({rid_b}).', 'At t={time_step} in {city}, what is the {modality} difference between {rid_a} and {rid_b}, first minus second?', 'Using the t={time_step} map for {city}, subtract the {modality} of {rid_b} from that of {rid_a}.'), 'U9': ('For {city} at t={time_step}, which {level} spatial unit has the highest {modality}?', 'At t={time_step} in {city}, identify the dominant {level} unit for {modality}.', 'Which {level} unit is the {modality} hotspot on the {city} map at t={time_step}?'), 'U10': ('At t={time_step}, report the {modality} value at {unit_phrase}.', 'For every city at t={time_step}, read {modality} at {unit_phrase}.', "Using each city's t={time_step} map, report {modality} for {unit_phrase}."), 'U11': ("At t={time_step}, compute each city's normalized {level}-level {modality} hotspot concentration C=(N*p_max-1)/(N-1), where p_max=max_i x_i/sum_j x_j and C=0 if the total is zero.", 'For every city at t={time_step}, calculate normalized {level}-level {modality} peak share C=(N*p_max-1)/(N-1); define C=0 when all spatial units are zero.', "Using the t={time_step} maps, report each city's normalized {level}-level {modality} concentration in [0,1] from C=(N*p_max-1)/(N-1)."), 'U12': ('At t={time_step}, which city has the highest normalized {level}-level {modality} hotspot concentration C=(N*p_max-1)/(N-1)?', 'Compare cities at t={time_step} using normalized {level}-level {modality} peak share. Which city is most concentrated?', 'Which city has the largest normalized {modality} concentration at the {level} level at t={time_step}, with C=(N*p_max-1)/(N-1)?'), 'U13': ('For {city}, report the two {modality} values at {pair_phrase}.', 'Read {modality} for the two specified region-time pairs in {city}: {pair_phrase}.', 'Using the {city} history, return the {modality} values for {pair_phrase} in the stated order.'), 'U14': ('For {city}, compute the {modality} value of the second region-time pair minus the first: {pair_phrase}.', 'Using {pair_phrase} in {city}, what is second {modality} value minus first?', 'For the two specified space-time points in {city} ({pair_phrase}), subtract the first {modality} value from the second.'), 'U15': ('For {city}, track the dominant {level}-level {modality} hotspot over t=1..8. Classify its movement as stationary, up, down, left, right, or mixed.', 'Across the eight historical maps of {city}, what is the main {level}-level {modality} hotspot movement: stationary, up, down, left, right, or mixed?', 'Using tied-hotspot centroids over t=1..8 in {city}, classify the {modality} hotspot path as stationary, up, down, left, right, or mixed.'), 'U16': ('For each city, report the two {modality} values at its specified region-time pairs: {pair_phrase}.', 'Read {modality} for the two specified space-time points in every city: {pair_phrase}.', "Using each city's history, return the two {modality} values for {pair_phrase} in order."), 'U17': ('For each city, compute second minus first {modality} value for its specified region-time pairs: {pair_phrase}.', 'Using {pair_phrase}, report the cross-space/time {modality} difference in every city, second minus first.', 'For each city, subtract the first region-time {modality} value from the second for {pair_phrase}.'), 'U18': ('Which city has the greatest mean normalized {level}-level {modality} hotspot movement over t=1..8, using tied-hotspot centroids?', 'Compare the cities by mean step distance of normalized tied-hotspot centroids over t=1..8 at the {level} level. Which is largest?', 'Using normalized centroid paths of all tied dominant {level} units, which city shows the largest average {modality} hotspot movement?'), 'P1': ('For {city}, predict the h=1..4 inflow and outflow pattern of {unit_phrase} as increasing, decreasing, stable, or fluctuating.', 'Using the 8-hour history for {city}, classify the future h=1..4 inflow and outflow sequences at {unit_phrase} as increasing, decreasing, stable, or fluctuating.', 'Forecast the future four-step trend category for both inflow and outflow at {unit_phrase} in {city}: increasing, decreasing, stable, or fluctuating.'), 'P2': ('For {city}, which {level} spatial unit will have the highest inflow and highest outflow at horizon h={horizon}?', 'At h={horizon} in {city}, predict the dominant {level} unit separately for inflow and outflow.', 'Using the {city} history, identify the future {level} inflow hotspot and outflow hotspot at h={horizon}.'), 'P3': ('For {city}, predict inflow and outflow of {unit_phrase} at horizons {horizon_set}.', 'Using the displayed history for {city}, forecast the h=1..4 inflow and outflow values at {unit_phrase}.', 'Estimate future inflow and outflow for {unit_phrase} in {city} over horizons {horizon_set}.'), 'P4': ('For {city}, predict the complete native-grid inflow and outflow maps at horizons {horizon_set}.', 'Using the 8-hour history for {city}, forecast all fine-grained native cells for inflow and outflow over h=1..4.', 'Estimate the full fine-grained two-channel {city} maps at horizons {horizon_set}.'), 'P5': ('For each city, predict the h=1..4 inflow and outflow pattern at {unit_phrase} as increasing, decreasing, stable, or fluctuating.', 'Using each 8-hour history, classify future inflow and outflow sequences at {unit_phrase} as increasing, decreasing, stable, or fluctuating.', 'Forecast the four-step inflow/outflow trend category for {unit_phrase} in every city.'), 'P6': ('For each city, which {level} spatial unit will have the highest inflow and highest outflow at h={horizon}?', "At horizon h={horizon}, predict each city's dominant {level} unit separately for inflow and outflow.", "Using each city's history, identify its future {level} inflow hotspot and outflow hotspot at h={horizon}."), 'P7': ('For each city, predict inflow and outflow at {unit_phrase} over horizons {horizon_set}.', 'Using each displayed history, forecast h=1..4 inflow and outflow values for {unit_phrase}.', 'Estimate future inflow and outflow over {horizon_set} for {unit_phrase} in every city.'), 'P8': ('For each city, predict the complete native-grid inflow and outflow maps at horizons {horizon_set}.', "Using each city's 8-hour history, forecast all fine-grained native cells for both channels over h=1..4.", 'Estimate the full fine-grained two-channel maps for all cities at horizons {horizon_set}.')}

def _validate_question_variants():
    missing = [tid for tid in ALL_TEMPLATE_IDS if tid not in QUESTION_VARIANTS]
    extra = [tid for tid in QUESTION_VARIANTS if tid not in TEMPLATES]
    wrong_count = [tid for tid in ALL_TEMPLATE_IDS if tid in QUESTION_VARIANTS and len(QUESTION_VARIANTS[tid]) != 3]
    if missing or extra or wrong_count:
        raise ValueError(f'Invalid QUESTION_VARIANTS configuration: missing={missing}, extra={extra}, wrong_count={wrong_count}')
_validate_question_variants()

def loss_mask_for_target_type(target_type: str) -> dict:
    value_types = {'scalar', 'vector', 'city_values', 'city_vectors', 'vector_pair', 'city_vector_pair'}
    tensor_types = {'tensor_sequence_2ch', 'city_tensor_sequence_2ch'}
    return {'text': 1, 'length': 0, 'value_mse': int(target_type in value_types), 'tensor_mse': int(target_type in tensor_types)}
